          { text: "Доложить по уставу", flags: { bd_reported: true }, effect: (p) => { p.asuraInfluence += 10; p.reputation += 5; return "Вас наградили. Через месяц вас перевели подальше от моста."; } },
          { text: "Продолжать встречаться тайно", flags: { bd_secret: true }, effect: (p) => { p.intellect += 8; p.reputation -= 8; return "Вы встречались год. Каждая встреча была преступлением, и это было частью её прелести."; } }
