          { text: "Никому не говорить", flags: { dm_secret: true }, effect: (p) => { p.intellect += 15; return "Вы хранили это тридцать лет и умерли с этим. Иногда молчание — это тоже наследство."; } },
          { text: "Уничтожить семейную книгу", flags: { dm_book: true }, effect: (p) => { p.intellect += 10; p.reputation -= 5; return "Книга горела вместе с записью. Вы не заметили, что страница с пророчеством не загорелась."; } }
