          { text: "Донести церкви", flags: { gg_reported: true }, effect: (p) => { p.reputation += 10; p.asuraInfluence += 10; p.hitogamiTrust += 5; return "Стража пришла на следующее собрание. Сорок человек вышли через другой вход и больше не собирались здесь."; } },
          { text: "Пройти мимо", flags: { gg_passed: true }, effect: (p) => { p.intellect += 5; return "Через полгода вы услышали, что седьмую богиню признали «полезной народной традицией». Никого не сожгли."; } }
