          { text: "Попросить ничего", flags: { gg_refused: true }, effect: (p) => { p.intellect += 25; p.northGodExp += 20; return "«Тогда я подожду.» С тех пор вы иногда просыпались в три часа ночи от того, что кто-то сидел у кровати."; } },
          { text: "Спросить, кто она", flags: { gg_who: true }, effect: (p) => { p.intellect += 20; p.hitogamiTrust += 10; return "«Я то, что остаётся, когда все боги уходят по делам. Их шесть. Меня никто не считал.»"; } }
