          { text: "Отказаться и уйти", flags: { gg_declined: true }, effect: (p) => { p.reputation += 10; p.intellect += 20; return "Вы уехали в другую страну. Через год узнали, что костры всё-таки были. Двадцать три человека."; } },
          { text: "Сдать их церкви, чтобы спасти", flags: { gg_betrayed: true }, effect: (p) => { p.reputation -= 30; p.asuraInfluence += 30; p.intellect += 15; return "Вы назвали имена и выторговали изгнание вместо казни. Они ушли живыми и прокляли вас на площади."; } }
