          { text: "Написать правду", flags: { ll_truth: true }, effect: (p) => { p.intellect += 25; p.reputation -= 10; return "Ваша книга о предке вышла под чужим именем. Её читали в трёх странах. Статую не убрали."; } },
          { text: "Сломать статую", flags: { ll_break: true }, effect: (p) => { p.reputation -= 20; p.asuraInfluence -= 15; p.intellect += 15; return "Вы обрушили её ночью. К утру на постаменте лежали цветы, а в вашу дверь стучали."; } }
