          { text: "Написать три строки", flags: { lh_short: true }, effect: (p) => { p.intellect += 30; p.reputation += 20; return "«Не берите чужого. Держите слово. Помните мальчика с овсом». Всё остальное оказалось неважным."; } },
          { text: "Не писать ничего", flags: { lh_none: true }, effect: (p) => { p.intellect += 10; p.reputation -= 10; return "Вы отложили лист. Потом ещё раз. Род разделился через месяц после вашей смерти — тихо, по-семейному, навсегда."; } }
