          { text: "Настоять на своём", flags: { lh_stand: true }, effect: (p) => { p.asuraInfluence += 20; p.reputation -= 15; return "Суд встал на вашу сторону. Младшая ветвь уехала навсегда. Через тридцать лет её потомки вернулись — с оружием."; } },
          { text: "Отдать спор на решение рода", flags: { lh_jury: true }, effect: (p) => { p.reputation += 25; p.intellect += 15; return "Род решил сам. Решение было хуже вашего — и держалось крепче, потому что было своё."; } }
