// ------------------------------------------------------------------

// Состояние сюжета хранится в player.story:
//   story.flags     — что уже случилось (решения)
//   story.done      — какие узлы пройдены
//   story.pending   — отложенные последствия { atYear, fn, text }
// ------------------------------------------------------------------
function ensureStoryState() {
  if (!player) return;
  if (!player.story || typeof player.story !== "object") player.story = {};
  if (!player.story.flags) player.story.flags = {};
  if (!player.story.done) player.story.done = [];
  if (!player.story.pending) player.story.pending = [];
  if (!player.story.lineDone) player.story.lineDone = [];
}

function hasStoryFlag(flag) {
  return !!(player?.story?.flags && player.story.flags[flag]);
}

function setStoryFlag(flag) {
  if (!player || !flag) return;
  ensureStoryState();
  player.story.flags[flag] = true;
}

// Условия, при которых узел доступен
function storyNodeAvailable(node) {
  if (!player || !node) return false;
  ensureStoryState();
  if (player.story.done.includes(node.id)) return false;
  if (player.children.filter(c => !c.isDead).length === 0 && node.reqChildren) return false;

  // Какой век мира: до Катаклизма — 1-я жизнь, после — другие рождения
  const gen = (typeof dynastyGeneration === "number") ? dynastyGeneration : 1;
  const year = worldState.currentWorldYear;
  const calamity = !!worldState.calamityOccurred;

  if (node.reqCalamity && !calamity) return false;
  if (node.reqNoCalamity && calamity) return false;
  // Сцены, которым нужен зрелый мир: открываются на 2-м рождении и позже
  if (node.reqGen && gen < node.reqGen) return false;
  if (node.reqMaxGen && gen > node.reqMaxGen) return false;
  // Сцены, привязанные к годам мира — чтобы поздние поколения жили в своём времени
  if (node.reqYear && year < node.reqYear) return false;
  if (node.reqMaxYear && year > node.reqMaxYear) return false;

  if (node.reqRegion && !node.reqRegion.includes(player.currentRegionKey)) return false;
  if (node.from && !hasStoryFlag(node.from)) return false;
  // Финал истории открывается, если история действительно была разыграна:
  // подходит любой из перечисленных «итоговых» флагов этой линии.
  if (node.fromAny && !node.fromAny.some(fn => {
    try { return !!fn(player); } catch (e) { return false; }
  })) return false;
  // Узел без `from` — стартовый, открывается по возрасту
  if (!node.from && player.age < (node.age || 0)) return false;
  if (node.from && player.age < (node.age || 0)) return false;
  return true;
}

// Собрать доступные сейчас сюжетные сцены
function getAvailableStoryNodes() {
  if (!player) return [];
  const out = [];
  STORY_LINES.forEach(line => {
    line.nodes.forEach(node => {
      if (storyNodeAvailable(node)) out.push({ line, node });
    });
  });
  return out;
}

// ------------------------------------------------------------------
// Сколько сцен из множества линий показывать в одном году.
// Веток много, и вываливать в окно все сразу — значит превратить
// дневник года в простыню. Показываем 2-3 самые важные, остальные
// ждут следующего года: вес узла и «продолжение ветки» в приоритете.
// ------------------------------------------------------------------
const YEAR_STORY_LIMIT = 3;
let yearStoryCache = { key: "", picks: [] };

function pickYearStoryNodes(limit, pool) {
  limit = limit || YEAR_STORY_LIMIT;
  if (!player) return [];
  ensureStoryState();

  const year = worldState.currentWorldYear;
  const cacheKey = `${year}::${player.age}`;
  const available = pool
    ? pool.map(node => ({ node, line: STORY_LINES.find(l => l.nodes.includes(node)) || { id: "?", icon: "📜", title: "?" } }))
    : getAvailableStoryNodes();
  const byId = {};
  available.forEach(a => { byId[a.node.id] = a; });
  const done = player.story.done || [];

  let picks;
  if (yearStoryCache.key === cacheKey) {
    // В этом году уже выбрано: убираем пройденное, добираем новыми сценами
    picks = yearStoryCache.picks.filter(p => byId[p.node.id] && !done.includes(p.node.id));
  } else {
    picks = [];
  }

  if (picks.length < limit) {
    const usedLines = picks.map(p => p.line.id);
    const pool = available
      .filter(a => !done.includes(a.node.id) && !picks.some(p => p.node.id === a.node.id))
      .map(a => {
        // Продолжение уже начатой ветки важнее новой завязки
        const continuation = a.node.from ? 25 : 0;
        const weight = a.node.weight || 20;
        const sameLinePenalty = usedLines.includes(a.line.id) ? 40 : 0;
        return { a, score: weight + continuation - sameLinePenalty + Math.random() * 8 };
      })
      .sort((x, y) => y.score - x.score);

    for (const item of pool) {
      if (picks.length >= limit) break;
      if (picks.some(p => p.line.id === item.a.line.id)) continue;
      picks.push(item.a);
      usedLines.push(item.a.line.id);
    }
    // Если все линии уже представлены — добираем просто по весу
    for (const item of pool) {
      if (picks.length >= limit) break;
      if (picks.some(p => p.node.id === item.a.node.id)) continue;
      picks.push(item.a);
    }
  }

  yearStoryCache = { key: cacheKey, picks };
  return picks.slice(0, limit);
}

// Сколько сцен ещё ждёт следующего года — чтобы игрок видел, что мир не пуст
function countYearStoryWaiting(limit, pool) {
  const shown = pickYearStoryNodes(limit, pool).length;
  const all = pool ? pool.length : getAvailableStoryNodes().length;
  return Math.max(0, all - shown);
}

// Отложенное последствие: сработает через N лет
function scheduleStoryConsequence(years, text, effectFn) {
  ensureStoryState();
  player.story.pending.push({
    atYear: worldState.currentWorldYear + Math.max(1, years),
    text,
    effect: effectFn ? effectFn.toString() : null
  });
}

// Вызывается каждый год: срабатывают отложенные последствия
function processStoryConsequences() {
  if (!player || !player.story || !Array.isArray(player.story.pending)) return;
  const now = worldState.currentWorldYear;
  const due = player.story.pending.filter(c => c.atYear <= now);
  if (!due.length) return;
  player.story.pending = player.story.pending.filter(c => c.atYear > now);
  due.forEach(c => {
    // Эффекты хранятся строкой, чтобы пережить сохранение
    if (c.effect) {
      try {
        const fn = new Function("p", "ws", "return (" + c.effect + ")(p, ws);");
        const res = fn(player, worldState);
        log(`⏳ <b>Отзвук прошлого:</b> ${c.text}${res ? " — " + res : ""}`);
        if (typeof queueYearExtra === "function") queueYearExtra("Отзвук прошлого", `${c.text}${res ? " — " + res : ""}`, "⏳");
      } catch (e) {
        console.warn("[BitTensei] Отложенное последствие:", e);
      }
    } else {
      log(`⏳ <b>Отзвук прошлого:</b> ${c.text}`);
      if (typeof queueYearExtra === "function") queueYearExtra("Отзвук прошлого", c.text, "⏳");
    }
  });
}

